function encode(obj) {
  return btoa(JSON.stringify(obj)).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
}

function decode(token) {
  try {
    return JSON.parse(atob(token.replaceAll("-", "+").replaceAll("_", "/")));
  } catch {
    return null;
  }
}

const token = encode({ v: 1, k: [88412] });
