function checkCursor(data, filters) {
  const key = Object.keys(filters).sort().map((n) => `${n}=${filters[n]}`).join("&");
  if (data?.v !== 1) return "version";
  if (data.f !== key) return "filters";
  const [at, id] = Array.isArray(data.k) ? data.k : [];
  if (typeof at !== "string" || Number.isNaN(Date.parse(at)) || !Number.isSafeInteger(id)) return "invalid";
  return "ok";
}

const good = { v: 1, f: "status=paid", k: ["2026-03-01T09:30:00.000Z", 42] };
console.log(checkCursor(good, { status: "paid" }));
console.log(checkCursor({ ...good, v: 0 }, { status: "paid" }));
console.log(checkCursor(good, { status: "shipped" }));
console.log(checkCursor({ ...good, k: ["yesterday", 42] }, { status: "paid" }));
console.log(checkCursor({ ...good, k: ["2026-03-01", "42"] }, { status: "paid" }));

