const changes = [
  { version: "2026-06-01", undo: ({ total_kobo, ...o }) => ({ ...o, total: total_kobo / 100 }) },
  { version: "2026-09-01", undo: ({ customer, ...o }) => ({ ...o, customer_id: customer.id }) },
];

function render(order, clientVersion) {
  return changes
    .filter((c) => c.version > clientVersion)
    .toReversed()
    .reduce((shape, c) => c.undo(shape), order);
}

