const MAJORS = ["v1", "v2"];
const DATED = ["2026-06-01", "2026-09-01"];

function resolveVersion(path, headers, fallback) {
  const major = path.split("/")[1];
  if (!MAJORS.includes(major)) return { status: 404 };
  const dated = headers["shop-version"] ?? fallback;
  if (!DATED.includes(dated)) return { status: 400 };
  return { major, dated };
}

console.log(resolveVersion("/v2/orders", {}, "2026-06-01"));
console.log(resolveVersion("/v1/orders", { "shop-version": "2026-09-01" }, "2026-06-01"));
console.log(resolveVersion("/v1/orders", { "shop-version": "latest" }, "2026-06-01"));
console.log(resolveVersion("/v9/orders", {}, "2026-06-01"));

