function breakingChanges(oldSample, newSample) {
  const problems = [];
  for (const [name, value] of Object.entries(oldSample)) {
    if (!(name in newSample)) problems.push(`removed ${name}`);
    else if (typeof newSample[name] !== typeof value) problems.push(`retyped ${name}`);
  }
  return problems;
}

console.log(breakingChanges(v1, v2));

